<?php declare(strict_types=1); $base=config('app.base_path'); $statuses=['PENDING','ACCEPTED','PACKING','READY','ASSIGNED','OUT_FOR_DELIVERY','DELIVERED','COMPLETED','CANCELLED','REJECTED']; ?>
<div class="page-header"><div><h1>Fresh Food Orders</h1><p>Manage the complete Fresh Food order lifecycle.</p></div><div class="page-actions"><a class="btn btn-secondary" href="<?= $base ?>/fresh-food">Fresh Food</a><a class="btn btn-primary" href="<?= $base ?>/fresh-food/orders/create">Create Test Order</a></div></div>
<div class="card"><div class="filters"><a class="filter <?= !$status?'active':'' ?>" href="<?= $base ?>/fresh-food/orders">All</a><?php foreach($statuses as $s): ?><a class="filter <?= $status===$s?'active':'' ?>" href="<?= $base ?>/fresh-food/orders?status=<?= $s ?>"><?= ucwords(strtolower(str_replace('_',' ',$s))) ?></a><?php endforeach; ?></div></div>
<div class="card"><table class="table"><thead><tr><th>Order</th><th>Business</th><th>Customer</th><th>Type</th><th>Total</th><th>Status</th><th>Created</th><th>Action</th></tr></thead><tbody><?php if(empty($orders)): ?><tr><td colspan="8"><div class="empty-state">No Fresh Food orders found.</div></td></tr><?php else: foreach($orders as $o): ?><tr><td><strong><?= htmlspecialchars($o['order_no'],ENT_QUOTES,'UTF-8') ?></strong></td><td><?= htmlspecialchars($o['business_name'],ENT_QUOTES,'UTF-8') ?></td><td><?= htmlspecialchars($o['customer_name'],ENT_QUOTES,'UTF-8') ?><br><small><?= htmlspecialchars((string)($o['customer_phone']??''),ENT_QUOTES,'UTF-8') ?></small></td><td><?= htmlspecialchars($o['order_type'],ENT_QUOTES,'UTF-8') ?></td><td>₹<?= number_format((float)$o['total'],2) ?></td><td><span class="badge"><?= htmlspecialchars($o['status'],ENT_QUOTES,'UTF-8') ?></span></td><td><?= htmlspecialchars((string)$o['created_at'],ENT_QUOTES,'UTF-8') ?></td><td><a class="link-button" href="<?= $base ?>/fresh-food/orders/<?= (int)$o['id'] ?>">View</a></td></tr><?php endforeach; endif; ?></tbody></table></div>
<style>.filters{display:flex;gap:8px;flex-wrap:wrap}.filter{padding:7px 10px;border:1px solid #ddd;border-radius:8px;text-decoration:none}.filter.active{font-weight:700}.badge{display:inline-block;padding:5px 8px;border-radius:999px;background:#eee;font-size:12px}</style>
